begin;
create table public.legal_work_notes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),message_id uuid not null references public.chat_messages(id),target_type text not null check(target_type in ('necesidad','expediente','contrato_sie','contrato_cp')),target_id uuid not null,snapshot jsonb not null,comment text not null default '' check(length(comment)<=4000),created_at timestamptz not null default now(),unique(owner_id,message_id,target_type,target_id));
create function public.ace_note_target_visible_v1(kind text,target uuid) returns boolean language sql stable security invoker set search_path=public as $$select case kind when 'necesidad' then exists(select 1 from necesidades where id=target) when 'expediente' then exists(select 1 from procurement_processes where id=target) when 'contrato_sie' then exists(select 1 from contratos_sie where id=target) when 'contrato_cp' then exists(select 1 from contratos_cp where id=target) else false end$$;
revoke all on function public.ace_note_target_visible_v1(text,uuid) from public;
grant execute on function public.ace_note_target_visible_v1(text,uuid) to authenticated;
alter table public.legal_work_notes enable row level security;
create policy notes_read on public.legal_work_notes for select to authenticated using(owner_id=auth.uid() and public.ace_note_target_visible_v1(target_type,target_id));
create policy notes_insert on public.legal_work_notes for insert to authenticated with check(owner_id=auth.uid() and public.ace_note_target_visible_v1(target_type,target_id) and exists(select 1 from chat_messages where id=message_id and role='assistant'));
grant select,insert on public.legal_work_notes to authenticated;
create index legal_work_notes_destination on public.legal_work_notes(owner_id,target_type,target_id,created_at desc);
create table public.legal_quality_cases(id uuid primary key default gen_random_uuid(),question text not null,expected_answer text not null default '',expected_sources jsonb not null default '[]',status text not null default 'pending' check(status in ('pending','reviewed')),review_note text not null default '',reviewer_id uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),check(status='pending' or (length(expected_answer)>0 and jsonb_array_length(expected_sources)>0 and length(review_note)>=10 and reviewer_id is not null and reviewed_at is not null)));
create table public.legal_quality_runs(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.legal_quality_cases(id),message_id uuid not null references public.chat_messages(id),reviewer_id uuid not null references auth.users(id),case_snapshot jsonb not null,response_snapshot jsonb not null,scores jsonb not null,reason text not null check(length(reason)>=10),indicators jsonb not null,created_at timestamptz not null default now());
alter table public.legal_quality_cases enable row level security;
alter table public.legal_quality_runs enable row level security;
create policy quality_cases_read on public.legal_quality_cases for select to authenticated using(exists(select 1 from profiles where id=auth.uid() and activo is not false and role in('admin','legal')));
create policy quality_cases_insert on public.legal_quality_cases for insert to authenticated with check(exists(select 1 from profiles where id=auth.uid() and activo is not false and role in('admin','legal')) and (status='pending' or reviewer_id=auth.uid()));
create policy quality_runs_read on public.legal_quality_runs for select to authenticated using(reviewer_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and activo is not false and role in('admin','legal')));
create policy quality_runs_insert on public.legal_quality_runs for insert to authenticated with check(reviewer_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and activo is not false and role in('admin','legal')) and exists(select 1 from legal_quality_cases where id=case_id and status='reviewed') and exists(select 1 from chat_messages where id=message_id and role='assistant'));
grant select,insert on public.legal_quality_cases,public.legal_quality_runs to authenticated;
insert into public.legal_quality_cases(question) values ('¿Qué elementos debe contener el requerimiento?'),('¿Cómo se distinguen el requerimiento y la estrategia de contratación?'),('¿Cuál es la regla y cuáles son las excepciones de la garantía de fiel cumplimiento?'),('¿Qué régimen corresponde cuando cambia la norma?'),('Compara dos versiones del mismo artículo'),('¿Qué información falta para resolver un supuesto de nulidad?'),('Explica un plazo y sus condiciones'),('¿Las fuentes disponibles permiten resolver una pregunta sin inventar una cita?');
commit;
